import { CORE_PALETTES, resolveTheme, themeCss } from "../src/theme/index.ts";

/**
 * The generated src/styles/themes.css: night/day by system appearance, the four core presets by data-theme. The app
 * applies every other built-in as inline variables, so the library themes add nothing to the stylesheet.
 */
export function renderThemesCss(): string {
  const night = resolveTheme(CORE_PALETTES.night);
  const day = resolveTheme(CORE_PALETTES.day);
  const parts = [
    "/* Generated by scripts/themes-css.ts from src/theme/builtins.ts. Do not edit by hand. */\n",
    themeCss(":root", day),
    `@media (prefers-color-scheme: dark) {\n${indent(themeCss(":root:not([data-theme])", night))}}\n`,
  ];
  for (const [name, palette] of Object.entries(CORE_PALETTES)) {
    parts.push(themeCss(`[data-theme="${name}"]`, resolveTheme(palette)));
  }
  return parts.join("\n");
}

function indent(css: string): string {
  return css
    .split("\n")
    .map((line) => (line === "" ? line : `  ${line}`))
    .join("\n");
}

if (import.meta.main) {
  await Bun.write(new URL("../src/styles/themes.css", import.meta.url), renderThemesCss());
}
